pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, address target, bytes memory data) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(target != address(0) && target != address(c));
        amount = bound(amount, 0, address(c).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Command{value: amount}(target, data);
        uint256 preBalance = address(c).balance;
        address owner = c.Owner();
        uint256 ownerPre = owner.balance;
        vm.prank(caller);
