pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 value, bytes memory data) public {
        // Ensure the caller is the owner (msg.sender = owner in setup)
        vm.assume(adr != address(c)); // prevent self-call issues
        uint256 balanceBefore = address(c).balance;

        // Call Command as owner
        c.Command{value: value}(adr, data);

        uint256 balanceAfter = address(c).balance;
        // The contract balance should not decrease after owner's Command (owner cannot drain)
        assertTrue(balanceAfter >= balanceBefore);
    }
}

