pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 value, bytes memory data) public {
        vm.assume(adr != address(c));
        vm.assume(adr != address(0));
        value = bound(value, 0, type(uint256).max);
        // Ensure the caller is not the owner so Command is called by non-owner
        address caller = address(uint160(uint256(keccak256(abi.encodePacked("caller")))));
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, adr, data));
        // Now call withdraw as the owner
        vm.prank(c.Owner());
        (bool revertFlag, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));
        assertTrue(revertFlag == false);
    }
}

