pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 value, bytes memory data) public {
        // Ensure adr is not the zero address (to avoid issues with transfer)
        vm.assume(adr != address(0));
        // Bound value to reasonable range
        value = bound(value, 0, 1000 ether);
        // Ensure the caller is the owner (since we need to test owner's withdraw behavior)
        // Actually we want to call Command with the owner as msg.sender
        // But the owner is the deployer (this contract in test), so we use vm.prank to set msg.sender to owner
        // The owner is c.Owner() which is the address of this test contract (since it deploys C)
        // So we can just call directly without prank as this contract is the owner
        // But we want to test that after a call to Command with msg.sender = owner, 
        // calling withdraw from owner does not revert.
        // Since the test contract is the owner, we can call Command directly.
        // Then we call withdraw and check it doesn't revert.
        // First, call Command(adr, data) with some value
        c.Command(adr, data);
        // Now call withdraw() – it should not revert in reference implementation
        // Use try-catch to capture revert
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(ok, "withdraw should not revert when called by owner after Command");
    }
}

