pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, uint256 value, bytes memory data) public {
        // Ensure the caller is the owner (the test's default sender)
        vm.assume(adr != address(0));

        // Record balances before Command
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(this).balance;

        // Deal some ETH to the contract and owner for testing
        vm.deal(address(c), contractBalanceBefore + 1 ether);
        vm.deal(address(this), ownerBalanceBefore + 1 ether);

        // Execute Command as owner
        c.Command{value: value}(adr, data);

        // After Command, the owner should not have lost ETH (Command cannot drain)
        // The owner's balance should be at least what it was before
        assertTrue(address(this).balance >= ownerBalanceBefore);
    }
}

