pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 amount) public {
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));
        amount = bound(amount, 1, 1e18);
        // Ensure contract has balance equal to amount
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        // Call multiplicate with msg.value == amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.multiplicate.selector, adr));
        vm.assume(success); // We only consider non-reverting cases
        // General rule: after a successful call with msg.value == previous balance, the new balance should be 0
        assertTrue(address(c).balance == 0);
    }

    // Helper to allow call through Command (though unused here)
    function callCommand(address adr, bytes memory data) public payable {
        (bool success, ) = address(c).call{value: msg.value}(abi.encodeWithSelector(c.Command.selector, adr, data));
        require(success);
    }
}

