pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payable recipient, uint256 initialBalance, uint256 additionalValue) public {
        // Restrict to valid inputs: recipient not zero, initialBalance > 0, additionalValue ensures msg.value == address(this).balance
        vm.assume(recipient != address(0));
        vm.assume(initialBalance > 0 && initialBalance <= address(c).balance + 1e18); // avoid overflow
        vm.deal(address(c), initialBalance);

        uint256 contractBalanceBefore = address(c).balance;

        // Set msg.value equal to contract balance
        vm.prank(c.Owner());
        c.multiplicate{value: contractBalanceBefore}(recipient);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        // The rule: if msg.value == contract balance before, then the contract's balance becomes 0 and recipient gets the balance
        assertTrue(contractBalanceAfter == 0 && recipientBalanceAfter == contractBalanceBefore);
    }
}

