pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 commandValue, uint256 multiplicateValue) public {
        // Bound inputs to reasonable ranges to avoid overflow issues
        commandValue = bound(commandValue, 0, 100 ether);
        multiplicateValue = bound(multiplicateValue, 0, 100 ether);

        // Ensure caller is owner to allow Command execution
        vm.assume(caller == c.Owner());

        // Fund the contract with some starting balance
        vm.deal(address(c), 10 ether);

        // Record balance before Command call
        uint256 balanceBefore = address(c).balance;

        // Execute Command with the given value
        bytes memory dummyData = "";
        c.Command{value: commandValue}(address(0), dummyData);

        // Now call multiplicate with msg.value = the original commandValue
        // (the bug is in the condition: original uses >=, mutant uses >)
        if (commandValue >= balanceBefore) {
            // In reference, this should succeed and transfer balance + commandValue
            // We check that the contract balance after multiplicate is 0
            c.multiplicate{value: commandValue}(address(0xdead));
            assertTrue(address(c).balance == 0);
        } else {
            // If commandValue < balanceBefore, multiplicate does nothing
            c.multiplicate{value: commandValue}(address(0xdead));
            // Balance should remain as after Command call
            assertTrue(address(c).balance == balanceBefore + commandValue);
        }
    }
}

