pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payable adr, uint256 amount, uint256 extra) public {
        amount = bound(amount, 1, 1e30);
        extra = bound(extra, 0, 1e30);
        vm.deal(address(c), amount);

        // Call Command to set balance (no data needed)
        c.Command(address(c), "");

        // Now balance is amount, call multiplicate with msg.value == balance
        uint256 balanceBefore = address(c).balance;
        vm.assume(balanceBefore > 0);
        vm.assume(adr != address(0));
        uint256 recipientBalanceBefore = adr.balance;

        // Prank as owner to call multiplicate
        vm.prank(c.Owner());
        (bool success, ) = address(c).call{value: balanceBefore}(abi.encodeWithSignature("multiplicate(address)", adr));

        assertTrue(success, "multiplicate call failed");

        // After the call, recipient should have received 2*balanceBefore
        uint256 recipientBalanceAfter = adr.balance;
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + 2 * balanceBefore, "recipient did not receive exact 2*balance");
    }
}

